import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long[] heap;
    static int heapSize;

    static void heapPush(long v) {
        int i = heapSize++;
        heap[i] = v;
        while (i > 0) {
            int p = (i - 1) / 2;
            if (heap[p] <= heap[i]) break;
            long t = heap[p];
            heap[p] = heap[i];
            heap[i] = t;
            i = p;
        }
    }

    static long heapPop() {
        long top = heap[0];
        heapSize--;
        if (heapSize > 0) {
            heap[0] = heap[heapSize];
            int i = 0;
            while (true) {
                int l = 2 * i + 1, rr = l + 1, m = i;
                if (l < heapSize && heap[l] < heap[m]) m = l;
                if (rr < heapSize && heap[rr] < heap[m]) m = rr;
                if (m == i) break;
                long t = heap[m];
                heap[m] = heap[i];
                heap[i] = t;
                i = m;
            }
        }
        return top;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[] q = new long[(int) n];
        for (int i = 0; i < q.length; i++) q[i] = Long.parseLong(next());
        long[] w = new long[(int) n];
        for (int i = 0; i < w.length; i++) w[i] = Long.parseLong(next());

        int cnt = (int) n;
        long[] keys = new long[cnt];
        for (int i = 0; i < cnt; i++) keys[i] = (w[i] * 1000000000L / q[i]) * 32768L + i;
        Arrays.sort(keys);
        heap = new long[cnt + 5];
        heapSize = 0;
        long sumq = 0, bn = -1, bd = 1;
        for (int t = 0; t < cnt; t++) {
            int i = (int) (keys[t] % 32768L);
            heapPush(-q[i]);
            sumq += q[i];
            if (heapSize > k) sumq += heapPop();
            if (heapSize == k) {
                long num = sumq * w[i], den = q[i];
                if (bn < 0 || num * bd < bn * den) {
                    bn = num;
                    bd = den;
                }
            }
        }
        System.out.println((bn + bd - 1) / bd);
    }
}
